// NEON NEBULA service worker (generated by tools/build.js)
const CACHE = 'neon-nebula-v1.0.0-d3cbb2fc';
const FILES = ["./","./index.html","./manifest.webmanifest","./icon-192.png","./icon-512.png","./icon-maskable-512.png","./apple-touch-icon.png"];
// other games share this web address, so only ever touch our own caches
const OURS = (k) => k.startsWith('neon-nebula-');
self.addEventListener('install', (e) => {
  // 'reload' skips the browser's HTTP cache so a new version never stores old files
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(FILES.map((u) => new Request(u, { cache: 'reload' })))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => OURS(k) && k !== CACHE).map((k) => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  if (e.request.method !== 'GET') return;
  e.respondWith(caches.open(CACHE).then((cache) => cache.match(e.request, { ignoreSearch: true }).then((hit) => hit || fetch(e.request).then((res) => {
    if (res.ok && new URL(e.request.url).origin === location.origin) cache.put(e.request, res.clone());
    return res;
  }).catch(() => (e.request.mode === 'navigate' ? cache.match('./index.html') : Response.error())))));
});
